create table if not exists mastering_master(entity_id char(36) primary key, changed_file bigint not null default 0, kind varchar(64), status varchar(32), canonical_id char(36), policy_digest varchar(128), kind_version varchar(128), body longtext not null, created_at datetime(6) not null default current_timestamp(6), index mastering_master_changed(changed_file, entity_id)) collate utf8mb4_bin;
create table if not exists mastering_profile(entity_id char(36) not null, position bigint not null, profile_id varchar(255), role varchar(64), valid_from varchar(40), valid_to varchar(40), body longtext not null, primary key(entity_id, position)) collate utf8mb4_bin;
create table if not exists mastering_file(file_key char(64) primary key, records bigint not null) collate utf8mb4_bin;
create table if not exists mastering_delivery(file_key char(64) not null, source_code varchar(64) not null, records bigint not null, repeated bigint not null, deferred bigint not null, primary key(file_key, source_code)) collate utf8mb4_bin;
create table if not exists mastering_identifier(namespace varchar(32) not null, value varchar(128) not null, entity_id char(36) not null, primary key(namespace, value, entity_id), index mastering_identifier_entity(entity_id)) collate utf8mb4_bin;
create table if not exists mastering_record(assertion_id varchar(128) primary key, subject varchar(255) not null, entity_id char(36), bound_id char(36), source_code varchar(64) not null, source_key varchar(255) not null, lei varchar(32), body longtext not null, index mastering_record_entity(entity_id), index mastering_record_subject(subject), index mastering_record_lei(lei)) collate utf8mb4_bin;
create table if not exists mastering_name_key(role varchar(16) not null, value varchar(64) not null, subject varchar(255) not null, primary key(role, value, subject), index mastering_name_key_subject(subject)) collate utf8mb4_bin;
create table if not exists mastering_review(subject varchar(255) not null, reason varchar(64) not null, assertion_id varchar(128), open_review bigint not null, primary key(subject, reason)) collate utf8mb4_bin;
create table if not exists mastering_decision(decision_id char(64) primary key, operation varchar(16) not null, left_id varchar(255), right_id varchar(255), body longtext not null, index mastering_decision_left(operation, left_id)) collate utf8mb4_bin;
create table if not exists mastering_withheld(subject varchar(255) not null, namespace varchar(32) not null, raw varchar(128) not null, primary key(subject, namespace, raw)) collate utf8mb4_bin;
create table if not exists mastering_deferred(deferred_id varchar(128) primary key, source_code varchar(64) not null, reason varchar(64) not null, blocking bigint not null, body longtext not null) collate utf8mb4_bin;
create table if not exists mastering_lookup(token char(64) not null, entity_id char(36) not null, primary key(token, entity_id), index mastering_lookup_entity(entity_id)) collate utf8mb4_bin;
create table if not exists mastering_lookup_progress(pin char(64) primary key, changed_file bigint not null, entity_id varchar(36) not null) collate utf8mb4_bin;
